    int r = sd_bus_default_system(&bus);
    if (r < 0) {
        *errnop = -r;
        return NSS_STATUS_UNAVAIL;
    }

    sd_bus_message* m = NULL;
    r = sd_bus_message_new_method_call(bus, &m, "org.freedesktop.machine1", "/org/freedesktop/machine1", "org.freedesktop.machine1.Manager", "MapGroup");
    if (r < 0) {
        *errnop = -r;
        sd_bus_unref(bus);
        return NSS_STATUS_UNAVAIL;
    }

    r = sd_bus_message_append(m, "(sn)", machine_name, gid);
    if (r < 0) {
        *errnop = -r;
        sd_bus_message_unref(m);
        sd_bus_unref(bus);
        return NSS_STATUS_UNAVAIL;
    }

    sd_bus_message* reply = NULL;
    r = sd_bus_call(bus, m, 0, NULL, &reply);
    if (r < 0) {
        *errnop = -r;
        sd_bus_unref(bus);
        return NSS_STATUS_UNAVAIL;
    }

    const char* group_name = NULL;
    char** members = NULL;
    r = sd_bus_message_read(reply, "(sa(sb))", &group_name, &members);
    if (r < 0) {
        *errnop = -r;
        sd_bus_message_unref(reply);
        sd_bus_unref(bus);
        return NSS_STATUS_UNAVAIL;
    }

    size_t name_len = strlen(group_name);
    size_t len = name_len + 1;
    for (char** member = members; *member; member++) {
        len += strlen(*member) + 1;
    }

    if (len > buflen) {
        *errnop = ERANGE;
        sd_bus_message_unref(reply);
        sd_bus_unref(bus);
        return NSS_STATUS_UNAVAIL;
    }

    gr->gr_name = buffer;
    strcpy(buffer, group_name);
    buffer += name_len + 1;

    gr->gr_passwd = "x";
    gr->gr_gid = gid;
    gr->gr_mem = (char**)members;

    sd_bus_message_unref(reply);
    sd_bus_unref(bus);
    *errnop = 0;
    return NSS_STATUS_SUCCESS;
}

