        return NSS_STATUS_NOTFOUND;
    }

    sd_bus* bus = NULL;
    int ret = sd_bus_open_system(&bus);
    if (ret < 0) {
        *errnop = -ret;
        return NSS_STATUS_UNAVAIL;
    }

    sd_bus_message* msg = NULL;
    ret = sd_bus_message_new_method_call(
        bus, &msg, "org.freedesktop.machine1", "/org/freedesktop/machine1",
        "org.freedesktop.machine1.Manager", "MapGroup");
    if (ret < 0 || !msg) {
        *errnop = -ret;
        sd_bus_flush_close_unref(bus);
        return NSS_STATUS_UNAVAIL;
    }

    ret = sd_bus_message_append(msg, "(sg)", machine_name, group_id);
    if (ret < 0) {
        *errnop = -ret;
        sd_bus_flush_close_unref(bus);
        return NSS_STATUS_UNAVAIL;
    }

    sd_bus_error error = SD_BUS_ERROR_NULL;
    sd_bus_message* reply = NULL;
    ret = sd_bus_call(bus, msg, 0, &error, &reply);
    if (ret < 0) {
        *errnop = -ret;
        sd_bus_flush_close_unref(bus);
        return NSS_STATUS_UNAVAIL;
    }

    const char* group_name = NULL;
    char** members = NULL;
    gid_t gid;

    ret = sd_bus_message_read(reply, "(s(ga))", &group_name, &gid, &members);
    if (ret < 0) {
        *errnop = -ret;
        sd_bus_flush_close_unref(bus);
        return NSS_STATUS_UNAVAIL;
    }

    size_t needed = strlen(group_name) + 1;
    for (char** m = members; m && *m; m++) {
        needed += strlen(*m) + 1;
    }

    if (needed > buflen) {
        *errnop = ENOMEM;
        sd_bus_flush_close_unref(bus);
        return NSS_STATUS_UNAVAIL;
    }

    char* p = buffer;
    strcpy(p, group_name);
    gr->gr_name = p;
    p += strlen(p) + 1;

    gr->gr_gid = gid;
    gr->gr_mem = (char**)malloc(sizeof(char*));
    if (!gr->gr_mem) {
        *errnop = ENOMEM;
        sd_bus_flush_close_unref(bus);
        return NSS_STATUS_UNAVAIL;
    }

    for (size_t i = 0; members[i]; i++) {
        strcpy(p, members[i]);
        gr->gr_mem[i] = p;
        p += strlen(p) + 1;
    }
    gr->gr_mem[i] = NULL;

    sd_bus_flush_close_unref(bus);
    *errnop = 0;
    return NSS_STATUS_SUCCESS;
}

